oxy_webhelp_navlinks = {"setup_db2_workload-d39536e34223":{"topics":[{"title":"Supported Db2 instance types","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects three Db2 instance types. The instance type is         determined automatically during discovery from the contents of the             <code class=\"ph codeph\">db2nodes.cfg<\/code> file.<\/p>","href":"db2\/supported_db2_instance_types.html","attributes":{"data-id":"supported_db2_instance_types"},"menu":{"hasChildren":false},"tocID":"supported_db2_instance_types-d39536e34237","topics":[]},{"title":"Configure Db2 instance","shortdesc":"<p class=\"shortdesc\">You can add Db2 hosts and Db2 database instances to <span class=\"ph\">RSC<\/span> so that <span class=\"ph\">RSC<\/span> can discover and protect the databases that belong to each         instance.<\/p>","href":"db2\/db2_instance_configuration.html","attributes":{"data-id":"db2_instance_configuration"},"menu":{"hasChildren":false},"tocID":"db2_instance_configuration-d39536e34253","next":"db2_instance_configuration-d39536e34253"},{"title":"Db2 pureScale","shortdesc":"<p class=\"shortdesc\">Db2 pureScale is a clustered system that facilitates collaborative and scalable         processing of database requests. With Db2 pureScale, you can achieve enhanced performance         and shared data management by adding members to the pureScale cluster.<\/p>","href":"db2\/db2_purescale.html","attributes":{"data-id":"db2_purescale"},"menu":{"hasChildren":false},"tocID":"db2_purescale-d39536e34295","next":"db2_purescale-d39536e34295"}]}};